// ============================================================
// GREETING AGENT: Static Greeting (v4.0 - NO LLM)
// Полностью статический ответ без использования LLM
// Экономит 100% API-вызовов для приветствий
// ============================================================

const context = $json;

// Статическое приветственное сообщение
const greetingMessage = '👋 Здравствуйте! Добро пожаловать в BestHotel!\n\n' +
  'Я — AI-рекрутер, и я помогу вам узнать о наших вакансиях и пройти короткое собеседование. 🤝\n\n' +
  'Мы ищем сотрудников для работы в отелях: горничные, администраторы, официанты и другие позиции.\n\n' +
  '🌍 Выберите удобный язык общения:';

return {
  // Context passthrough
  user_id: context.user_id,
  chat_id: context.chat_id,
  session_id: context.session_id,
  user_message: context.user_message,
  known_data: context.known_data || {},
  language: context.language || 'ru',
  route_category: context.route_category,
  first_name: context.first_name,
  username: context.username,

  // Response
  response_message: greetingMessage,
  final_message: greetingMessage,
  extracted_data: {},
  interview_complete: false,
  show_language_buttons: true,
  needs_escalation: false
};
